L = 64;
g = kaiser(L, 10);
S = zeros(L/2+1, 5);
S(9, :) = 1;
x = ifsst(S, g);
fprintf('%.5f\n', x(1:3));
fprintf('%.5f\n', 2/(L*g(L/2+1)));

w = hann(64, 'periodic');
disp(iscola(w, 32, 'ola'))
disp(iscola(w, 32, 'wola'))
[tf, cst, dev] = iscola(w, 32, 'ola');
fprintf('constant %.4f, within rounding: %d\n', cst, dev < 1e-12);
disp(iscola(w, 48))

fs = 1000; n = (0:255)';
x = sin(2*pi*100*n/fs) + 0.5*sin(2*pi*250*n/fs);
w = hann(64, 'periodic');
s = stft(x, fs, 'Window', w, 'OverlapLength', 48, 'FFTLength', 64);
[y, t] = istft(s, fs, 'Window', w, 'OverlapLength', 48, 'FFTLength', 64, 'ConjugateSymmetric', true);
fprintf('%d samples, t ends at %.3f s\n', numel(y), t(end));
fprintf('max error below 1e-10: %d\n', max(abs(y - x(1:numel(y)))) < 1e-10);

fs = 1000; t = (0:255)'/fs;
x = sin(2*pi*100*t) + 0.5*sin(2*pi*250*t);
[s, f, tt, p] = spectrogram(x, hann(64), 32, 64, fs);
disp(size(s))
disp(tt')
[~, i] = max(p(:, 3));
fprintf('strongest bin in segment 3: %.2f Hz\n', f(i));

fs = 1000; t = (0:255)'/fs;
x = sin(2*pi*100*t);
[~, ~, ~, p1] = spectrogram(x, hann(64), 32, 64, fs);
[~, ~, ~, p2] = spectrogram(x, hann(64), 32, 64, fs, 'power');
fprintf('psd peak %.4f, power peak %.4f\n', max(p1(:, 3)), max(p2(:, 3)));

fs = 1000; n = (0:255)';
x = sin(2*pi*100*n/fs);
[s, f, t] = stft(x, fs, 'Window', hann(64, 'periodic'), 'OverlapLength', 32, 'FFTLength', 64, 'FrequencyRange', 'onesided');
disp(size(s))
disp(f(1:3)')
disp(t(1:3)')
[~, i] = max(abs(s(:, 3)));
fprintf('peak at %.2f Hz\n', f(i));

fs = 1000; n = (0:255)';
x = sin(2*pi*100*n/fs) + 0.5*sin(2*pi*250*n/fs);
w = hann(64, 'periodic');
s = stft(x, fs, 'Window', w, 'OverlapLength', 48, 'FFTLength', 64, 'FrequencyRange', 'onesided');
[y, t, info] = stftmag2sig(abs(s), 64, fs, 'Window', w, 'OverlapLength', 48, 'FrequencyRange', 'onesided', 'MaxIterations', 50);
fprintf('%d samples, %d iterations, exit flag %d\n', numel(y), info.NumIterations, info.ExitFlag);
s2 = stft(y, fs, 'Window', w, 'OverlapLength', 48, 'FFTLength', 64, 'FrequencyRange', 'onesided');
fprintf('relative magnitude error %.2f\n', norm(abs(s2) - abs(s), 'fro')/norm(abs(s), 'fro'));

fs = 1000; t = (0:511)'/fs;
x = cos(2*pi*(50*t + 100*t.^2));
[s, f, tt] = spectrogram(x, hann(64), 48, 64, fs);
[fr, ir] = tfridge(abs(s), f);
disp(size(fr))
disp(round(fr(1:4:end)'))
disp(round(50 + 200*tt(1:4:end)))

n = (0:255)';
x = cos(2*pi*0.05*n) + 0.5*cos(2*pi*0.2*n);
[imf, res, info] = vmd(x, 'NumIMFs', 2, 'CentralFrequencies', [0.04 0.18]);
disp(size(imf))
disp(round(info.CentralFrequencies'*100)/100)
fprintf('exit flag %d\n', info.ExitFlag);
fprintf('modes + residual rebuild x: %d\n', max(abs(sum(imf, 2) + res - x)) < 1e-10);

fs = 100; n = (0:31)';
y = exp(1j*2*pi*(5*n/fs + 20*(n/fs).^2));
[d, f, t] = wvd(y, fs);
disp(size(d))
for c = [8 32 56]
  [~, i] = max(d(:, c));
  fprintf('t = %.3f s: %.0f Hz (expected %.0f)\n', t(c), f(i), 5 + 40*t(c));
end

fs = 1000; t = (0:255)'/fs;
x = sin(2*pi*100*t);
y = 2*sin(2*pi*100*t + 0.5);
[s, f, tt, cs] = xspectrogram(x, y, hann(64), 32, 64, fs);
disp(size(s))
[m, i] = max(s(:, 3));
fprintf('%.2f Hz, magnitude %.4f, phase %.3f rad\n', f(i), m, angle(cs(i, 3)));

fs = 1000; n = (0:299)';
x = (1 + 0.5*cos(2*pi*7*n/fs)) .* sin(2*pi*300*n/fs);
[es, f] = envspectrum(x, fs);
disp(size(es))
k = f > 2;
fk = f(k); ek = es(k);
[~, i] = max(ek);
fprintf('peak at %.2f Hz (frequency step %.2f Hz)\n', fk(i), f(2));

fs = 1000; N = 512; f = (0:N/2)'*fs/N; w = 2*pi*f;
H = zeros(size(f));
w1 = 2*pi*50;  H = H + 1  ./(w1^2 - w.^2 + 2i*0.02*w1*w);
w2 = 2*pi*120; H = H + 0.5./(w2^2 - w.^2 + 2i*0.03*w2*w);
[fn, dr, ms, ofrf] = modalfit(H, f, fs, 3);
disp(round(fn'*10)/10)
disp(round(dr'*100)/100)
fprintf('relative fit error %.2f\n', max(abs(ofrf - H))/max(abs(H)));

fs = 1000; n = (0:2047)';
x = zeros(size(n));
for k = 1:40
  x = x + sin(2*pi*(7.3*k)*n/fs + k^2);
end
r = 0.95; th = 2*pi*100/fs;
y = filter(1, [1 -2*r*cos(th) r^2], x);
[frf, f, coh] = modalfrf(x, y, fs, 256, 128, 'Sensor', 'dis');
disp(size(frf))
[~, i] = max(abs(frf));
fprintf('peak at %.1f Hz, coherence there %.2f\n', f(i), coh(i));

fs = 1000; n = 1024; t = (0:n-1)'/fs;
rpm = 600 + 300*t;
ph = 2*pi*cumtrapz(t, rpm/60);
x = cos(ph) + 0.6*cos(3*ph);
[sp, o] = orderspectrum(x, fs, rpm);
disp(size(sp))
[pk, li] = findpeaks(sp, 'SortStr', 'descend', 'NPeaks', 2);
fprintf('peak near order %.2f, level %.2f\n', o(li(1)), pk(1));
fprintf('peak near order %.2f, level %.2f\n', o(li(2)), pk(2));

x = [-2 1 -3 5 -1 3 -4 4 -2]';
c = rainflow(x);
disp(c)
fprintf('equivalent full cycles: %g\n', sum(c(:, 1)));

fs = 1000; n = 1024; t = (0:n-1)'/fs;
rpm = 600 + 300*t;
ph = 2*pi*cumtrapz(t, rpm/60);
x = cos(ph) + 0.6*cos(3*ph);
[map, f, r, tt] = rpmfreqmap(x, fs, rpm, 10);
disp(size(map))
for c = [1 size(map, 2)]
  [~, i] = max(map(:, c));
  fprintf('%.0f rpm (%.1f Hz): strongest at %.1f Hz\n', r(c), r(c)/60, f(i));
end

fs = 1000; n = 1024; t = (0:n-1)'/fs;
rpm = 600 + 300*t;
ph = 2*pi*cumtrapz(t, rpm/60);
x = cos(ph) + 0.6*cos(3*ph);
[map, o, r, tt] = rpmordermap(x, fs, rpm);
disp(size(map))
disp(round(r'))
[~, i] = max(map(:, 3));
fprintf('strongest order in column 3: %.2f\n', o(i));

fs = 1000; t = (0:2999)'/fs;
x = double(mod(5*t, 1) < 0.4);
[rpm, tt, tp] = tachorpm(x, fs, 'FitType', 'linear');
disp(size(rpm))
disp(round(rpm([1 1500 end])'))
disp(tp(1:3)')

fs = 100; t = (0:499)'/fs;
tp = (0:0.5:4.5)';
clean = sin(2*pi*2*t);
x = clean + 0.5*sin(2*pi*3.3*t);
[y, tt, p, rpm] = tsa(x, fs, tp);
disp(size(y))
fprintf('speed %g rpm, one rotation lasts %.2f s\n', rpm, tt(end) + 1/fs);
fprintf('error before %.3f, after %.3f\n', max(abs(x(1:50) - clean(1:50))), max(abs(y - clean(1:50))));
